    Bug 520582 - Adjust unread status of NNTP headers when downloading. r=mkmelin


    This patch sets the unread status of downloaded headers according to the newsrc file as soon as they are added to the message database. Previously this was only done when the view was initialized, but `nsMsgDBView::AdjustReadFlag` wasn't called on elided messages in collapsed threads. Especially after repairing the folder or getting the next n messages, this could result in an incorrect and fragile view.

    Differential Revision: https://phabricator.services.mozilla.com/D225617

diff --git a/mailnews/base/src/MsgKeySet.sys.mjs b/mailnews/base/src/MsgKeySet.sys.mjs
index cb5586ce085..da9c75b8313 100644
--- a/mailnews/base/src/MsgKeySet.sys.mjs
+++ b/mailnews/base/src/MsgKeySet.sys.mjs
@@ -119,7 +119,7 @@ export class MsgKeySet {
         newRanges.push([cursorStart, cursorEnd]);
         cursorStart = start;
         cursorEnd = end;
-      } else {
+      } else if (end > cursorEnd) {
         // Overlapped, merge them.
         cursorEnd = end;
       }
diff --git a/mailnews/base/test/unit/test_MsgKeySet.js b/mailnews/base/test/unit/test_MsgKeySet.js
index 736cba449fd..71287907394 100644
--- a/mailnews/base/test/unit/test_MsgKeySet.js
+++ b/mailnews/base/test/unit/test_MsgKeySet.js
@@ -40,6 +40,16 @@ add_task(function testAddRange() {
   ok(keySet.has(22));
   ok(keySet.has(199));
   equal(keySet.toString(), "2-29,102,199");
+
+  // Add overlapping ranges.
+  keySet.addRange(20, 40);
+  equal(keySet.toString(), "2-40,102,199");
+  keySet.addRange(10, 30);
+  equal(keySet.toString(), "2-40,102,199");
+  keySet.addRange(1, 20);
+  equal(keySet.toString(), "1-40,102,199");
+  keySet.addRange(1, 150);
+  equal(keySet.toString(), "1-150,199");
 });

