     if (groupInfo) {
@@ -116,10 +120,8 @@ export class NntpNewsGroup {
         }
         start = args.downloadAll ? start : end - this._server.maxArticles + 1;
         if (this._server.markOldRead) {
-          this._readKeySet = new MsgKeySet(
